custom_css:
/* 美化名字：黑巧克力燕麦 · 醇厚中性暖调（低饱和·高对比·无粉感） */
/* 二创作者：mukamuka */
/* 框架编写/整理：墨千尾（discord@这对吗/inkfoxxxx） */
/* 修复顶部导航栏图标全部相同的问题，恢复各自原本的图标 */

/* === 字体导入 === */
@import url("https://fonts.googleapis.com/css2?family=Great+Vibes&family=Dancing+Script:wght@400;700&display=swap");
@import url("https://fontsapi.zeoseven.com/438/main/result.css"); /* 汇文正楷 */
@import url("https://fontsapi.zeoseven.com/480/main/result.css"); /* 仓耳飞白字体 */

@font-face {
  font-family: "✏️";
  src: url("✏️");
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

/* === 全局变量（黑巧克力燕麦 · 中性暖褐，无粉调） === */
:root {
  --main-bg: #cbb9a8; /* 燕麦谷物底色，暖灰褐，不粉不黄 */
  --panel-bg: rgba(248, 242, 236, 0.98); /* 奶油燕麦面板 */
  --text-light: #201712; /* 极深可可 */
  --text-dim: #5a4a3e; /* 暖灰褐 */
  --accent-green: #6d5342; /* 黑巧粉，低饱和深褐 */
  --accent-gold: #af917c; /* 焦糖奶霜 */
  --border-color: rgba(109, 83, 66, 0.55); /* 半透深可可 */
  --gradient-green-gold: linear-gradient(135deg, #6d5342 0%, #af917c 100%);
  --gradient-dark: linear-gradient(180deg, #4e3f32 0%, #32271e 100%); /* 深黑巧栏，低饱和 */
  --ui-color-sec: rgba(248, 242, 236, 0.96);
}

body {
  font-family: "Microsoft YaHei", "PingFang SC", sans-serif;
  color: var(--text-light);
  background-color: var(--main-bg);
}

/* === 全局文字颜色（强制深色，高对比） === */
body,
div,
p,
span,
a,
button,
input,
textarea,
select,
option,
label,
.drawer-content,
.options-content,
.mes_text,
.mes_text * {
  color: var(--text-light) !important;
}
.mes_timer,
.tokenCounterDisplay,
.mesIDDisplay,
.ch_name .timestamp {
  color: var(--text-dim) !important;
}

/* === 所有弹窗、抽屉、列表背景统一为浅色半透明 === */
.drawer-content,
.options-content,
#table_drawer_content,
.popup-content,
.ui-widget-content,
.select2-dropdown,
.select2-container--default .select2-results,
.jse-main,
[data-v-81d837f8].TH-custom-tailwind,
#select_chat_popup,
#select_chat_div,
.select_chat_block,
.select_chat_block_wrapper,
.chatBackupsList,
#dialogue_popup,
#character_popup,
#world_popup {
  background: var(--panel-bg) !important;
  backdrop-filter: blur(10px);
  border: 1px solid var(--border-color) !important;
}

.select_chat_block {
  background: rgba(248, 242, 236, 0.94) !important;
  margin-bottom: 8px;
  border-radius: 8px;
  padding: 8px;
}
.select_chat_block:hover {
  background: rgba(255, 252, 248, 1) !important;
}

/* === 顶栏（低饱和黑巧克力，图标柔和） === */
#top-settings-holder {
  background: var(--gradient-dark);
  border-bottom: 1px solid var(--accent-green);
  box-shadow: 0 2px 8px rgba(30, 20, 14, 0.4);
}
#top-bar {
  background: transparent !important;
}

#top-settings-holder .drawer-icon {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  width: auto !important;
  height: auto !important;
  font-size: 20px !important;
  line-height: 1;
}

/* 图标使用柔和米灰，无粉感 */
#top-settings-holder .drawer-icon::before {
  color: transparent !important;
  background: linear-gradient(135deg, #e0d2c6 0%, #ede0d4 100%);
  -webkit-background-clip: text;
  background-clip: text;
  transition: all 0.3s ease;
}

#top-settings-holder .drawer-icon:hover::before {
  filter: drop-shadow(0 0 6px #e2ccbc);
  transform: scale(1.1);
}

#top-settings-holder .drawer-icon.openIcon {
  background: transparent !important;
}
#top-settings-holder .drawer-icon.openIcon::before {
  color: transparent !important;
  background: linear-gradient(135deg, #d4c2b2 0%, #e5d4c4 100%);
  -webkit-background-clip: text;
  background-clip: text;
}

/* === 底栏（低饱和黑巧克力，输入框极致对比） === */
#send_form {
  background: var(--gradient-dark);
  border-top: 1px solid var(--accent-green) !important;
  border-radius: 15px 15px 0 0 !important;
  padding: 10px;
  box-shadow: 0 -2px 8px rgba(30, 20, 14, 0.4);
}
#send_textarea {
  background: rgba(255, 255, 252, 1) !important;
  border: 1px solid rgba(109, 83, 66, 0.7) !important;
  border-radius: 10px !important;
  color: #120c08 !important;
  padding: 8px !important;
}
#send_form [class*="fa-"] {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
#send_form [class*="fa-"]::before {
  font-size: 18px;
  color: transparent !important;
  background: linear-gradient(135deg, #d4c2b2 0%, #ebdbcc 100%);
  -webkit-background-clip: text;
  background-clip: text;
  transition: all 0.2s ease;
}
#send_form [class*="fa-"]:hover::before {
  filter: drop-shadow(0 0 5px #e2ccbc);
  transform: scale(1.1);
}

/* === 聊天区域（完美布局原封不动 · 仅配色替换为燕麦底色） === */
#sheld {
  height: calc(
    var(--doc-height, 100vh) - var(--topBarBlockSize, 45px) - 1px
  ) !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

#chat {
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  overflow-y: scroll !important;
  overflow-x: hidden !important;
  max-height: calc(
    var(--doc-height, 100vh) - var(--topBarBlockSize, 45px) - 20px
  ) !important;
  padding-left: 6px !important;
  padding-right: 0px;
  display: flex;
  flex-direction: column;
  gap: 0px;
}

.mesAvatarWrapper {
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100% !important;
}

.mesAvatarWrapper .avatar {
  margin: 0 0 35px 0 !important;
  width: 100% !important;
  height: 320px !important;
  flex: 0 0 auto !important;
  position: relative;
  pointer-events: none !important;
}

.mesAvatarWrapper .avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover;
  object-position: 50% 20%;
  border-radius: 12px 12px 0 0 !important;
  border: none !important;
  image-rendering: -webkit-optimize-contrast;
  image-rendering: high-quality;

  -webkit-mask-image: linear-gradient(
    to bottom,
    black 60%,
    rgba(0, 0, 0, 0.8) 75%,
    rgba(0, 0, 0, 0.4) 88%,
    rgba(0, 0, 0, 0.1) 95%,
    transparent 100%
  );
  mask-image: linear-gradient(
    to bottom,
    black 60%,
    rgba(0, 0, 0, 0.8) 75%,
    rgba(0, 0, 0, 0.4) 88%,
    rgba(0, 0, 0, 0.1) 95%,
    transparent 100%
  );
}

.mesAvatarWrapper .avatar img {
  pointer-events: auto !important;
  -webkit-user-drag: none !important;
  user-select: none !important;
  -webkit-touch-callout: none !important;
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: contents;
  color: var(--text-dim);
}

#chat .ch_name {
  position: static;
  align-items: flex-end;
  padding: calc(var(--mainFontSize) * 0.8) 0;
  font-size: 0.9em;
  color: var(--text-light);
}

#chat .ch_name::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 1px;
  background-color: var(--border-color);
}

.mes {
  width: 100%;
  flex-direction: column !important;
  align-items: center !important;
  border: none !important;
  margin: 0 0 0px 0 !important;
  padding: 0 !important;
  background-color: transparent !important;
  position: relative !important;
}

.mes .ch_name .name_text {
  position: absolute !important;
  top: 330px !important;
  left: 0 !important;
  right: 0 !important;
  margin: 0 auto !important;
  width: 100% !important;
  text-align: center !important;
  font-family: "TsangerFeiBai W03", "Great Vibes", cursive !important;
  font-size: 1.8em !important;
  font-weight: normal !important;
  color: var(--accent-gold) !important;
  z-index: 99 !important;
  pointer-events: none !important;
  display: block !important;
  opacity: 1 !important;
  visibility: visible !important;

  text-shadow:
    0 1px 3px rgba(250, 240, 230, 0.9),
    0 2px 6px rgba(109, 83, 66, 0.6),
    0 0 8px rgba(175, 145, 124, 0.6) !important;
}

.mes_text {
  padding: calc(var(--mainFontSize) * 0.8) 0 0 0;
}

.mes_text q,
.mes_text “q” {
  color: #876250;
  font-style: italic;
}

.mes_text i,
.mes_text em {
  color: #6a5242;
}

.mes_block {
  width: 98%;
  padding-left: 0;
  padding-bottom: 15px;
}

.last_mes .mes_text {
  padding-right: 0;
}

.last_mes .mesAvatarWrapper {
  padding-bottom: 0;
}

div[is_user="false"].last_mes .mes_block {
  padding-bottom: 50px;
}

/* === 燕麦色气泡配色（柔和，层次分明） === */

div[is_user="true"].mes {
  background: linear-gradient(
    to bottom,
    rgba(255, 254, 250, 0.98),
    rgba(252, 246, 238, 0.96)
  ) !important;
  backdrop-filter: blur(12px);
  border: 1px solid rgba(175, 145, 124, 0.7) !important;
  border-top: 4px solid var(--accent-gold) !important;
  border-radius: 12px;
  margin-bottom: 20px !important;
  box-shadow: 0 4px 12px rgba(70, 48, 34, 0.25) !important;
}

div[is_user="true"] .avatar img {
  box-shadow: none !important;
  border: none !important;
}

div[is_user="false"].mes {
  background: linear-gradient(
    to bottom,
    rgba(248, 242, 236, 0.98),
    rgba(240, 230, 222, 0.96)
  ) !important;
  backdrop-filter: blur(12px);
  border: 1px solid rgba(109, 83, 66, 0.7) !important;
  border-top: 4px solid var(--accent-green) !important;
  border-radius: 12px;
  margin-bottom: 20px !important;
  box-shadow: 0 4px 12px rgba(70, 48, 34, 0.25) !important;
}

div[is_user="false"] .avatar img {
  box-shadow: none !important;
  border: none !important;
}

.last_mes .swipeRightBlock {
  margin: 0 10px 0 0;
}

.swipe_left {
  left: calc(8px + 5px);
}

.swipeRightBlock {
  flex-direction: row-reverse;
  bottom: calc(var(--swipeCounterHeight) + var(--swipeCounterMargin));
}

.swipes-counter {
  margin-bottom: 4px;
}

#chat .mes.selected {
  background-color: rgba(109, 83, 66, 0.25) !important;
}

body.documentstyle #chat .ch_name::after {
  width: 0;
}

body.documentstyle #chat .mes .mes_block {
  margin-right: 0;
  padding-bottom: 15px;
}

/* === 收藏栏横向滑动（修复头像双层框） === */
#HotSwapWrapper {
  overflow: hidden;
}
#HotSwapWrapper > div {
  overflow: auto hidden !important;
  display: flex !important;
  flex-wrap: nowrap !important;
  justify-content: flex-start !important;
  gap: 12px !important;
  min-height: 120px !important;
  padding: 10px 0 !important;
  scrollbar-width: thin;
}
#HotSwapWrapper > div .avatar {
  width: 90px !important;
  height: 90px !important;
  flex: 0 0 auto !important;
  border-radius: 12px !important;
  overflow: hidden !important;
  box-shadow: 0 2px 8px rgba(70, 48, 34, 0.4) !important;
  border: none !important;
  background: transparent !important;
  padding: 0 !important;
}
#HotSwapWrapper > div .avatar img {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border: none !important;
  border-radius: inherit !important;
}

/* === 表格（燕麦风格 · 结构优化版） === */
.mes_text {
  position: relative;
  padding-bottom: 20px;
}

.mes_text table {
  display: block;
  width: auto;
  min-width: 100%;
  max-width: max-content;
  margin: 12px 0;
  border-collapse: separate;
  border-spacing: 0;
  border-radius: 12px;
  background: linear-gradient(
    145deg,
    rgba(255, 252, 248, 0.94) 0%,
    rgba(252, 246, 238, 0.98) 100%
  );
  background-clip: padding-box;
  border: 1px solid rgba(109, 83, 66, 0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  overflow-x: auto;
  overflow-y: visible;
  padding-bottom: 6px;
}

.mes_text table > thead,
.mes_text table > tbody,
.mes_text table > tr {
  display: table;
  width: 100%;
  table-layout: auto;
}

.mes_text table > thead {
  display: table-header-group;
}

.mes_text table > tbody {
  display: table-row-group;
}

.mes_text table tr {
  display: table-row;
}

.mes_text table thead tr {
  background: linear-gradient(145deg, #6d5342 0%, #af917c 100%);
}

.mes_text table th,
.mes_text table td {
  display: table-cell;
  padding: 12px 16px;
  text-align: left;
  vertical-align: top;
  white-space: nowrap;
  font-size: calc(var(--mainFontSize) * 0.9);
  line-height: 1.4;
  border: 1px solid rgba(109, 83, 66, 0.45);
}

.mes_text table th {
  background: transparent;
  color: #201712;
  font-weight: 600;
  text-align: center;
  border-bottom-width: 2px;
  border-color: rgba(109, 83, 66, 0.8);
}

.mes_text table td {
  color: var(--text-light);
}

.mes_text table tbody tr:hover {
  background: rgba(109, 83, 66, 0.25) !important;
}

.mes_text table tbody tr:nth-child(even) {
  background: rgba(125, 95, 75, 0.08);
}

.mes_text table tbody tr:nth-child(even):hover {
  background: rgba(109, 83, 66, 0.3) !important;
}

.mes_text table::-webkit-scrollbar {
  height: 4px;
}
.mes_text table::-webkit-scrollbar-track {
  background: rgba(185, 165, 150, 0.7);
  border-radius: 4px;
  margin: 0 12px;
  border: 0.5px solid rgba(109, 83, 66, 0.6);
  box-shadow: inset 0 0 3px rgba(0, 0, 0, 0.05);
}
.mes_text table::-webkit-scrollbar-thumb {
  background: var(--gradient-green-gold);
  border-radius: 4px;
  border: 1px solid rgba(175, 145, 124, 0.7);
  box-shadow: 0 0 4px rgba(109, 83, 66, 0.6);
  min-width: 50px;
  max-width: 70vw;
}
.mes_text table::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(
    90deg,
    #6d5342 0%,
    var(--accent-gold) 50%,
    #6d5342 100%
  );
  box-shadow: 0 0 6px rgba(175, 145, 124, 0.9);
}

/* ========= 普通按钮、输入框、下拉框（燕麦配色） ========= */
.menu_button,
.interactable,
button,
input[type="button"],
input[type="submit"],
input[type="reset"],
.popup-button-ok,
.popup-button-cancel,
#dialogue_del_mes_ok,
#dialogue_del_mes_cancel,
.redWarningBG,
.red_button {
  background: rgba(248, 242, 236, 0.96) !important;
  border: 1px solid rgba(109, 83, 66, 0.7) !important;
  color: #201712 !important;
  box-shadow: none !important;
  transition: none !important;
  cursor: pointer;
}

.menu_button:hover,
.interactable:hover,
button:hover {
  background: rgba(255, 255, 252, 1) !important;
  border-color: #af917c !important;
  transform: none !important;
  box-shadow: none !important;
}

#delete_button,
#dialogue_del_mes_ok,
.redWarningBG,
.red_button {
  background: rgba(115, 72, 62, 0.92) !important;
  border-color: #73483e !important;
  color: white !important;
}
#delete_button:hover,
#dialogue_del_mes_ok:hover {
  background: #5e382f !important;
}

input,
textarea,
select,
.text_pole {
  background: rgba(255, 255, 252, 0.98) !important;
  border: 1px solid rgba(109, 83, 66, 0.7) !important;
  color: #120c08 !important;
}

input:focus,
textarea:focus,
select:focus {
  background: #ffffff !important;
  border-color: #af917c !important;
  outline: none;
}

input[type="checkbox"] {
  accent-color: #6d5342;
  appearance: none;
  width: 18px;
  height: 18px;
  background: rgba(248, 242, 236, 0.96);
  border: 1.5px solid rgba(109, 83, 66, 0.8);
  border-radius: 4px;
  cursor: pointer;
}
input[type="checkbox"]:checked {
  background: linear-gradient(145deg, #6d5342, #af917c);
  border-color: transparent;
}
input[type="checkbox"]:checked::after {
  content: "✓";
  color: #ffffff;
  font-size: 13px;
  display: block;
  text-align: center;
  line-height: 1;
}
::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}
::-webkit-scrollbar-track {
  background: rgba(170, 150, 135, 0.6);
  border-radius: 10px;
}
::-webkit-scrollbar-thumb {
  background: var(--gradient-green-gold);
  border-radius: 10px;
}

/* ========= 修复特定组件的黑色色块 ========= */
.jse-menu,
.jse-navigation-bar,
.jse-search-box-container,
.jse-contents {
  background: rgba(248, 242, 236, 0.98) !important;
  color: var(--text-light) !important;
}
.jse-button,
.jse-navigation-bar-button {
  background: var(--ui-color-sec) !important;
  border: 1px solid var(--border-color) !important;
  color: var(--text-light) !important;
  border-radius: 4px;
  padding: 4px 8px;
}
.jse-button:hover,
.jse-navigation-bar-button:hover {
  background: #ffffff !important;
  border-color: var(--accent-gold) !important;
}
.jse-separator {
  background: var(--border-color) !important;
}
.jse-key {
  color: #5a4a3e !important;
}
.jse-value.jse-string {
  color: #876250 !important;
}
.jse-value.jse-number {
  color: #201712 !important;
}
.jse-expand svg {
  fill: #201712 !important;
}
.dataBankAttachments,
.dataBankAttachments .attachmentsList,
.dataBankAttachments .attachmentListItem {
  background: rgba(248, 242, 236, 0.98) !important;
  color: var(--text-light) !important;
}
.dataBankAttachments input,
.dataBankAttachments select,
.dataBankAttachments textarea {
  background: rgba(255, 255, 252, 0.98) !important;
  border: 1px solid var(--border-color) !important;
  color: var(--text-light) !important;
}
.dataBankAttachments .menu_button,
.dataBankAttachments .interactable,
.dataBankAttachments .right_menu_button {
  background: var(--ui-color-sec) !important;
  border: 1px solid var(--border-color) !important;
  border-radius: 6px !important;
  color: var(--text-light) !important;
  padding: 4px 10px !important;
  box-shadow: none;
}
.dataBankAttachments .menu_button:hover,
.dataBankAttachments .interactable:hover {
  background: #ffffff !important;
  border-color: var(--accent-gold) !important;
}
.dataBankAttachments .attachmentListItem .right_menu_button {
  background: transparent !important;
  border: none !important;
  padding: 2px !important;
}
.dataBankAttachments .attachmentListItem .right_menu_button i {
  color: var(--text-dim) !important;
}
.dataBankAttachments .attachmentListItem .right_menu_button:hover i {
  color: var(--accent-gold) !important;
}
.actionButtonsModal {
  background: rgba(248, 242, 236, 0.98) !important;
  border: 1px solid var(--border-color) !important;
  backdrop-filter: blur(8px);
}
.actionButtonsModal .list-group-item {
  background: transparent !important;
  color: var(--text-light) !important;
}
.actionButtonsModal .list-group-item:hover {
  background: rgba(109, 83, 66, 0.18) !important;
}
#Backgrounds.drawer-content,
#bg-header-fixed,
#bg_tab_panel,
.bg_list .bg_example {
  background: rgba(248, 242, 236, 0.98) !important;
  backdrop-filter: blur(8px);
}
#bg-filter,
#background_fitting {
  background: rgba(255, 255, 252, 0.98) !important;
  border: 1px solid var(--border-color) !important;
  color: var(--text-light) !important;
}
.bg_tab_button {
  background: rgba(248, 242, 236, 0.85) !important;
  border: 1px solid var(--border-color) !important;
  color: var(--text-light) !important;
}
.bg_tab_button.ui-state-active {
  background: #ffffff !important;
  border-color: var(--accent-gold) !important;
}
.mes_reasoning_header {
  background: linear-gradient(
    45deg,
    rgba(175, 145, 124, 0.4),
    rgba(109, 83, 66, 0.4)
  );
  border: 1px solid rgba(175, 145, 124, 0.85);
  border-radius: 8px;
  padding: 6px 16px;
}
.mes_reasoning {
  background: rgba(248, 242, 236, 0.88);
  border-left: 3px solid #af917c;
  border-radius: 0 8px 8px 0;
